// One item per approved send, with per-lane sender identity and suppression.
// Suppressed = lead missing/undeliverable or lead already churned/superseded/unsubscribed.
const FROM_BY_LANE = {
  mm_ctrl: 'CTRL <ctrl@themindmaker.ai>',
  fractionl_pulse: 'Fractionl <pulse@fractionl.ai>',
  fractionl_circle: 'Fractionl <circle@fractionl.ai>',
  legibility: 'Legibility <hello@themindmaker.ai>',
  full_time: 'Full Time <fulltime@themindmaker.ai>',
};
const rows = $('Fetch approved sends').all().map(i => i.json).flat();
const out = [];
for (const s of rows) {
  const lead = s.leads || {};
  const suppress = !lead.email || ['churned', 'superseded'].includes(lead.status);
  out.push({ json: {
    send_id: s.id,
    lead_id: s.lead_id,
    suppress,
    from: FROM_BY_LANE[s.lane] || 'Mindmaker <hello@themindmaker.ai>',
    to: lead.email || null,
    subject: s.rendered_subject || '(no subject)',
    html: s.rendered_body || '',
  }});
}
return out;

// Pair each Resend response with its send; classify sent vs failed.
const prepared = $('Suppress or send?').all().map(i => i.json);
const responses = $('Send via Resend').all();
const out = [];
responses.forEach((r, idx) => {
  const p = prepared[idx] || {};
  const ok = !r.json?.error && (r.json?.id || r.json?.data?.id);
  out.push({ json: {
    send_id: p.send_id,
    lead_id: p.lead_id,
    ok: Boolean(ok),
    resend_id: r.json?.id || r.json?.data?.id || null,
    error: ok ? null : JSON.stringify(r.json?.error || r.error || 'unknown resend failure').slice(0, 500),
    now: new Date().toISOString(),
  }});
});
return out;
